import pandas as pd

def viewers_turned_streamers(sessions: pd.DataFrame) -> pd.DataFrame:
    df = sessions.sort_values(by=['user_id', 'session_start']).copy()
    first_sess = df.groupby('user_id').first().reset_index()
    viewer_first_users = set(first_sess[first_sess['session_type'] == 'Viewer']['user_id'])

    streamer_df = df[(df['user_id'].isin(viewer_first_users)) & (df['session_type'] == 'Streamer')]
    if streamer_df.empty:
        return pd.DataFrame(columns=['user_id', 'sessions_count'])

    res = streamer_df.groupby('user_id').size().reset_index(name='sessions_count')
    return res.sort_values(by=['sessions_count', 'user_id'], ascending=[False, False])
